const fmt = (n: number, digits = 2) => n.toLocaleString("en-US", { maximumFractionDigits: digits, minimumFractionDigits: digits });
const short = (value: string, start = 5, end = 4) => `${value.slice(0, start)}…${value.slice(-end)}`;
const pathFor = (points: { progress: number; price: number }[], width: number, height: number, pad = 8) => {
  const safePoints = points.length ? points : [{ progress: 0, price: 0 }];
  const prices = safePoints.map((point) => Number.isFinite(point.price) ? point.price : 0);
  const min = Number.isFinite(Math.min(...prices)) ? Math.min(...prices) : 0;
  const max = Number.isFinite(Math.max(...prices)) ? Math.max(...prices) : min;
  const safeSpan = Math.max(1e-9, Number.isFinite(max - min) ? max - min : 0);
  const finiteCoord = (coord: number, fallback: number) => Number.isFinite(coord) ? coord : fallback;
  return safePoints.map((point, index) => {
    const progress = Math.max(0, Math.min(1, Number.isFinite(point.progress) ? point.progress : 0));
    const price = Number.isFinite(point.price) ? point.price : min;
    const x = finiteCoord(pad + progress * (width - pad * 2), pad);
    const y = finiteCoord(height - pad - ((price - min) / safeSpan) * (height - pad * 2), pad);
    return `${index ? "L" : "M"}${x.toFixed(2)},${y.toFixed(2)}`;
  }).join(" ");
};
const BASE58 = "123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz";
function base58Encode(bytes: Uint8Array) { let value = BigInt(0); for (const byte of bytes) value = (value << BigInt(8)) + BigInt(byte); let output = ""; while (value > BigInt(0)) { const remainder = Number(value % BigInt(58)); output = BASE58[remainder] + output; value /= BigInt(58); } for (const byte of bytes) { if (byte !== 0) break; output = `1${output}`; } return output.padStart(44, "1").slice(0, 44); }
function fallbackAddress(seed: string) { const bytes = new Uint8Array(32); let hash = 2166136261; for (let index = 0; index < bytes.length; index += 1) { for (const char of `${seed}:${index}`) hash = Math.imul(hash ^ char.charCodeAt(0), 16777619); bytes[index] = hash & 255; } return base58Encode(bytes); }
async function deriveAddress(seedParts: string[]) { const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(seedParts.join("|"))); return base58Encode(new Uint8Array(digest)); }

