function MiniCurve({ preset }: { preset: Preset }) {
  const points = curveSeries(preset, preset.curve, 28); const initialPrice = points[0]?.price || 1; const path = points.map((point, index) => { const progress = Math.max(0, Math.min(1, point.progress)); const ratio = Math.max(1, point.price / initialPrice); const x = 3 + progress * 94; const y = 29 - Math.max(0, Math.min(1, (ratio - 1) / 3.4)) * 24; return `${index ? "L" : "M"}${x.toFixed(2)},${y.toFixed(2)}`; }).join(" "); const fill = `${path} L97,29 L3,29 Z`; const gradientId = `mini-${preset.id.replace(/[^a-z0-9]/gi, "-")}`;
  return <svg viewBox="0 0 100 32" preserveAspectRatio="none" className="mini-curve" aria-label={`${preset.curve} curve preview`}><defs><linearGradient id={gradientId} x1="0" x2="0" y1="0" y2="1"><stop offset="0" stopColor="#F97316" stopOpacity=".4"/><stop offset="1" stopColor="#F97316" stopOpacity="0"/></linearGradient></defs><path d="M3 29H97" stroke="#2A3342" strokeWidth=".7"/><path d={fill} fill={`url(#${gradientId})`}/><path d={path} fill="none" stroke="#F97316" strokeWidth="1.8" vectorEffect="non-scaling-stroke"/></svg>;
}

function CurveChart({ config, raisedPct, previewPct }: { config: DbcConfig; raisedPct: number; previewPct?: number }) {
  const width = 1120; const height = 280; const pad = 48;
  let activePoints = curveSeries(config, config.curve, 80); let reference = curveSeries(config, "Flat", 80);
  if (!activePoints.length) activePoints = [{ progress: 0, price: 0 }, { progress: 1, price: 0 }];
  if (!reference.length) reference = [{ progress: 0, price: 0 }, { progress: 1, price: 0 }];
  activePoints = activePoints.map((point) => ({ progress: Number.isFinite(point.progress) ? point.progress : 0, price: Number.isFinite(point.price) ? point.price : 0 }));
  const activePath = pathFor(activePoints, width, height, pad); const referencePath = pathFor(reference, width, height, pad); const fillPath = `${activePath} L${width - pad},${height - pad} L${pad},${height - pad} Z`;
  const [hover, setHover] = useState<number | null>(null); const finite = (value: number, fallback = 0) => Number.isFinite(value) ? value : fallback; const clamp = (value: number, low: number, high: number) => Math.max(low, Math.min(high, finite(value, low)));
  const rawMin = Math.min(...activePoints.map((point) => finite(point.price))); const rawMax = Math.max(...activePoints.map((point) => finite(point.price))); const min = finite(rawMin, 0); const max = finite(rawMax, min); const safeSpan = Math.max(1e-9, finite(max - min, 0)); const safeCoordinate = (coord: number) => finite(coord, pad);
  const y = (price: number) => safeCoordinate(height - pad - ((finite(price, min) - min) / safeSpan) * (height - pad * 2)); const x = (progress: number) => safeCoordinate(pad + clamp(progress, 0, 1) * (width - pad * 2));
  const currentIndex = Math.max(0, Math.min(activePoints.length - 1, Math.round((activePoints.length - 1) * clamp(raisedPct, 0, 100) / 100))); const selectedIndex = hover === null ? currentIndex : Math.max(0, Math.min(activePoints.length - 1, hover)); const current = activePoints[currentIndex] ?? activePoints[0]; const selected = activePoints[selectedIndex] ?? current;
  const safePreview = clamp(previewPct ?? 0, 0, 100); const previewPoint = activePoints[Math.max(0, Math.min(activePoints.length - 1, Math.round((activePoints.length - 1) * safePreview / 100)))] ?? current; const fdv = finite(selected.price * finite(config.initialVirtualBaseReserve));
  return <div className="chart-workspace grid h-[270px] w-full grid-cols-[minmax(0,1fr)_190px] items-center gap-3"><svg viewBox={`0 0 ${width} ${height}`} preserveAspectRatio="none" className="block h-full min-w-0 w-full" onMouseLeave={() => setHover(null)} onMouseMove={(event) => { const rect = event.currentTarget.getBoundingClientRect(); const progress = rect.width > 0 ? (event.clientX - rect.left) / rect.width : 0; setHover(Math.round(clamp(progress, 0, 1) * (activePoints.length - 1))); }}>
    <defs><pattern id="dotGrid" width="18" height="18" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r="1" fill="#94A3B8" fillOpacity=".11"/></pattern><linearGradient id="meteorArea" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stopColor="#FB923C" stopOpacity=".34"/><stop offset=".48" stopColor="#F97316" stopOpacity=".13"/><stop offset="1" stopColor="#EA580C" stopOpacity="0"/></linearGradient><filter id="curveGlow" x="-20%" y="-20%" width="140%" height="140%"><feDropShadow dx="0" dy="0" stdDeviation="4" floodColor="#F97316" floodOpacity=".6"/></filter></defs>
    <rect x={safeCoordinate(pad)} y={safeCoordinate(pad)} width={safeCoordinate(width - pad * 2)} height={safeCoordinate(height - pad * 2)} fill="url(#dotGrid)" rx="10"/>
    {[0, .25, .5, .75, 1].map((p) => <line key={p} x1={safeCoordinate(pad)} x2={safeCoordinate(width - pad)} y1={y(min + (max - min) * p)} y2={y(min + (max - min) * p)} stroke="#1E2330" strokeWidth="1"/>)}
    <path d={fillPath} fill="url(#meteorArea)"/><path d={referencePath} fill="none" stroke="#38BDF8" strokeOpacity=".7" strokeDasharray="6 5" strokeWidth="2"/><path d={activePath} fill="none" stroke="#F97316" strokeWidth="3" strokeLinecap="round" filter="url(#curveGlow)"/>
    <line x1={x(1)} x2={x(1)} y1={safeCoordinate(pad)} y2={safeCoordinate(height - pad)} stroke="#38BDF8" strokeDasharray="4 4"/><text x={safeCoordinate(width - pad - 4)} y={safeCoordinate(pad - 8)} fill="#7DD3FC" fontSize="13" textAnchor="end">100% GRADUATION → DAMM v2</text>
    <circle cx={x(selected.progress)} cy={y(selected.price)} r="6" fill="#090B10" stroke="#F97316" strokeWidth="3"/><circle cx={x(current.progress)} cy={y(current.price)} r="3" fill="#F97316"/>{Number.isFinite(previewPct) && <><circle cx={x(previewPoint.progress)} cy={y(previewPoint.price)} r="5" fill="#090B10" stroke="#F97316" strokeWidth="2"/><line x1={x(previewPoint.progress)} x2={x(previewPoint.progress)} y1={safeCoordinate(pad)} y2={safeCoordinate(height - pad)} stroke="#F97316" strokeDasharray="2 4" opacity=".7"/></>}
    {hover !== null && <line x1={x(selected.progress)} x2={x(selected.progress)} y1={safeCoordinate(pad)} y2={safeCoordinate(height - pad)} stroke="#F97316" strokeDasharray="3 3" opacity=".7"/>}
    {([0, .25, .5, .75, 1] as number[]).map((p) => <text key={p} x={safeCoordinate(3)} y={safeCoordinate(y(min + (max - min) * p) + 4)} fill="#CBD5E1" fontSize="13">{fmt(finite(min + (max - min) * p), 4)}</text>)}
    {[0, .25, .5, .75, 1].map((p) => <text key={p} x={x(p)} y={safeCoordinate(height - 8)} fill="#CBD5E1" fontSize="13" textAnchor={p === 0 ? "start" : p === 1 ? "end" : "middle"}>{p * 100}%</text>)}
  </svg><div className="glass-hud w-[190px] shrink-0 p-3"><div className="mb-2 text-[13.5px] uppercase tracking-[.14em] text-[#9AA4B5]">{hover === null ? "CURRENT RESERVE" : "CURVE INSPECTOR"}</div><div className="grid grid-cols-2 gap-x-3 gap-y-1.5 text-[13.5px]"><span className="text-[#8791A1]">Reserve</span><b className="font-mono">{fmt(finite(selected.progress * 100), 2)}%</b><span className="text-[#8791A1]">Spot price</span><b className="font-mono">{fmt(finite(selected.price), 6)}</b><span className="text-[#8791A1]">sqrtPrice</span><b className="font-mono">{fmt(finite(Math.sqrt(Math.max(0, selected.price))), 6)}</b><span className="text-[#8791A1]">Implied FDV</span><b className="font-mono">{fmt(fdv, 0)}</b></div></div></div>;
}
function FeeChart({ config }: { config: DbcConfig }) {
  const points = Array.from({ length: 40 }, (_, i) => ({ progress: i / 39, price: feeAtSlot(config, i / 39 * config.feeDecaySlots) }));
  const path = pathFor(points, 640, 120, 18); const fill = `${path} L622,102 L18,102 Z`;
  return <div className="relative h-36 px-2 pt-2"><svg viewBox="0 0 640 120" className="h-full w-full"><defs><linearGradient id="feeArea" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stopColor="#F59E0B" stopOpacity=".24"/><stop offset="1" stopColor="#F59E0B" stopOpacity="0"/></linearGradient></defs><path d={fill} fill="url(#feeArea)"/><path d={path} fill="none" stroke="#F59E0B" strokeWidth="2.5"/><line x1="18" x2="622" y1="102" y2="102" stroke="#1E2330"/><text x="18" y="116" fill="#8791A1" fontSize="13">Slot 0</text><text x="18" y="10" fill="#FCD34D" fontSize="13">{config.startFeeBps} BPS</text><text x="155" y="116" fill="#8791A1" fontSize="13">Cliff · {config.feeCliffSlots}</text><text x="622" y="116" fill="#8791A1" fontSize="13" textAnchor="end">Steady State · {config.feeDecaySlots}</text><text x="622" y="10" fill="#6EE7B7" fontSize="13" textAnchor="end">{config.endFeeBps} BPS</text></svg></div>;
}

